import sqlite3
import hashlib
import os
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/var/lib/app/metrics.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-Api-Key', '')
        if not key:
            return jsonify({'error': 'missing key'}), 401
        key_hash = hashlib.sha256(key.encode()).hexdigest()
        db = get_db()
        row = db.execute('SELECT org_id FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
        if not row:
            return jsonify({'error': 'invalid key'}), 403
        g.org_id = row['org_id']
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v1/metrics/timeseries', methods=['GET'])
@require_api_key
def timeseries():
    metric = request.args.get('metric', 'cpu_usage')
    host = request.args.get('host', '')
    window = request.args.get('window', '1h')
    align = request.args.get('align', 'start')

    # Validate metric name against known metrics
    valid_metrics = ['cpu_usage', 'memory_usage', 'disk_io', 'network_rx', 'network_tx', 'request_count', 'error_rate']
    if metric not in valid_metrics:
        return jsonify({'error': 'unknown metric'}), 400

    # Validate window format
    valid_windows = ['5m', '15m', '30m', '1h', '6h', '12h', '24h', '7d']
    if window not in valid_windows:
        return jsonify({'error': 'invalid window'}), 400

    # Build query with validated metric and parameterized host filter
    base_query = f"SELECT timestamp, value FROM {metric}_series WHERE org_id = ?"
    params = [g.org_id]

    if host:
        base_query += " AND host = ?"
        params.append(host)

    # Apply time alignment - align parameter controls ORDER BY / time bucketing
    # Valid values: 'start', 'end', 'middle', or a strftime pattern
    if align in ('start', 'end', 'middle'):
        align_expr = {'start': 'timestamp', 'end': 'timestamp DESC', 'middle': 'timestamp'}[align]
        base_query += f" ORDER BY {align_expr}"
    else:
        # Custom alignment expression for time bucketing
        # e.g., align=strftime('%H',timestamp) groups by hour
        base_query += f" GROUP BY {align} ORDER BY {align}"

    base_query += " LIMIT 1000"

    try:
        db = get_db()
        rows = db.execute(base_query, params).fetchall()
        return jsonify({'data': [{'ts': r['timestamp'], 'v': r['value']} for r in rows]})
    except Exception as e:
        app.logger.error(f"Query failed: {e}")
        return jsonify({'error': 'query execution failed'}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8081)
